mapper.sql:
SELECT RESOURCE_COORD_ID FROM (
 SELECT RESOURCE_COORD_ID FROM (
  SELECT R.RESOURCE_COORD_ID FROM SMT_AUTH_SELECTION_RESOURCE R
  WHERE R.BATCH_ID=#{batch} AND R.RESOURCE_COORD_ID IS NOT NULL
  MINUS
  SELECT C.RESOURCE_COORD_ID FROM SMT_AUTH_SOURCE_RESOURCE C
  JOIN SMT_AUTH_OPERATION_TARGET T ON T.ID=C.TARGET_ID
  WHERE T.BATCH_ID=#{batch}
 ) L
 WHERE RESOURCE_COORD_ID>#{after}
 ORDER BY RESOURCE_COORD_ID
) WHERE ROWNUM<=#{limit}

mapper.select:

SELECT DISTINCT PARK_ID,SUBJECT_ID,DEVICE_ID,ACCESS_TYPE,RESOURCE_TYPE,RESOURCE_ID,SERVICE_TYPE,CREDENTIAL_CHANNEL FROM (
SELECT D.PARK_ID,T.CARD_NO SUBJECT_ID,T.DEVICE_CODE DEVICE_ID,'DIRECT' ACCESS_TYPE,'PERSON' RESOURCE_TYPE,T.CARD_NO RESOURCE_ID,TO_CHAR(T.SERVICE_TYPE) SERVICE_TYPE,'FACE' CREDENTIAL_CHANNEL FROM SMT_DEVICE_TASK T JOIN SMT_DEVICE D ON D.ID=T.DEVICE_CODE WHERE T.DEVICE_TYPE=#{cardDeviceType} AND T.SERVICE_TYPE IN (#{employeeService},#{faceUpdateService}) AND T.CARD_NO IN  AND D.PARK_ID IN #{p}
UNION ALL
SELECT PARK_ID,CARD_NO SUBJECT_ID,DEVICE_CODE DEVICE_ID,'DIRECT' ACCESS_TYPE,'PERSON' RESOURCE_TYPE,CARD_NO RESOURCE_ID,TO_CHAR(SERVICE_TYPE) SERVICE_TYPE,'FACE' CREDENTIAL_CHANNEL FROM SMT_TASK_DOWN_RECORD WHERE DEVICE_TYPE=#{cardDeviceType} AND SERVICE_TYPE IN (#{employeeService},#{faceUpdateService}) AND CARD_NO IN  AND PARK_ID IN #{p}
UNION ALL
SELECT D.PARK_ID,T.CARD_NO SUBJECT_ID,T.DEVICE_CODE DEVICE_ID,'ISC' ACCESS_TYPE,'PERSON' RESOURCE_TYPE,T.CARD_NO RESOURCE_ID,TO_CHAR(T.SERVICE_TYPE) SERVICE_TYPE,'FACE' CREDENTIAL_CHANNEL FROM SMT_ISC_DEVICE_TASK T JOIN SMT_DEVICE D ON D.ID=T.DEVICE_CODE WHERE T.DEVICE_TYPE=#{cardDeviceType} AND T.SERVICE_TYPE IN (#{employeeService},#{faceUpdateService}) AND T.CARD_NO IN  AND D.PARK_ID IN #{p}
UNION ALL
SELECT PARK_ID,CARD_NO SUBJECT_ID,DEVICE_CODE DEVICE_ID,'ISC' ACCESS_TYPE,'PERSON' RESOURCE_TYPE,CARD_NO RESOURCE_ID,TO_CHAR(SERVICE_TYPE) SERVICE_TYPE,'FACE' CREDENTIAL_CHANNEL FROM SMT_ISC_DOWN_RECORD WHERE DEVICE_TYPE=#{cardDeviceType} AND SERVICE_TYPE IN (#{employeeService},#{faceUpdateService}) AND CARD_NO IN  AND PARK_ID IN #{p}
UNION ALL SELECT R.PARK_ID,R.SUBJECT_ID,R.DEVICE_ID,R.ACCESS_TYPE,R.RESOURCE_TYPE,R.RESOURCE_ID,R.SERVICE_TYPE,R.CREDENTIAL_CHANNEL FROM SMT_AUTH_RESOURCE_COORD R WHERE R.SUBJECT_TYPE='STAFF' AND R.SERVICE_TYPE != TO_CHAR(#{appPerfectService}) AND R.SUBJECT_ID IN  AND R.PARK_ID IN #{p}
) WHERE DEVICE_ID IS NOT NULL
